-- ============================================================
-- Bestial Discipline: notes
-- ============================================================
--
-- TODO.md: "Bestial Discipline (3, 4): Increases the focus regeneration of your
-- pets by 100%, and your critical hits restore 5 focus to your pet. (2 ranks)"
--
-- No C++.  The focus regen half was already +50/+100% (Effect1,
-- ADD_FLAT_MODIFIER, MiscValue 8, class mask 0x20000000) and is untouched; only
-- the unused Effect2 is filled in.
--
-- ProcFlags 65876 = 0x10154
--   0x00000004 PROC_FLAG_DONE_MELEE_AUTO_ATTACK
--   0x00000010 PROC_FLAG_DONE_SPELL_MELEE_DMG_CLASS
--   0x00000040 PROC_FLAG_DONE_RANGED_AUTO_ATTACK
--   0x00000100 PROC_FLAG_DONE_SPELL_RANGED_DMG_CLASS
--   0x00010000 PROC_FLAG_DONE_SPELL_MAGIC_DMG_CLASS_NEG
-- "Your critical hits" is read broadly on purpose: the magic flag is what lets
-- Arcane Shot and Explosive Shot count, and leaving it out would make the talent
-- quietly worse for the two specs most likely to take a Focus bonus seriously.
--
-- HitMask 2 = PROC_HIT_CRITICAL is the whole trigger condition.
-- SpellPhaseMask 2 is mandatory once 0x10 is present (SpellMgr.cpp:2113).
-- Cooldown 1000 keeps a Volley or a Multi-Shot burst from dumping the pet's
-- whole Focus bar back in one tick.
--
-- One negative row covers both ranks: the amount is flat 5 at rank 1 and rank 2
-- alike, so nothing differs per rank.
DELETE FROM `spell_proc` WHERE `SpellId` = -19590;
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(-19590, 0, 0, 0, 0, 0, 65876, 0, 2, 2, 0, 0, 0, 100, 1000, 0);

-- EffectImplicitTargetA1 = 5 (TARGET_UNIT_PET) is safe HERE because the caster
-- is the hunter.  This is the mirror image of the trap documented at
-- WarlockDemonPets.cpp:534, where 32554 broke precisely because the DEMON was
-- the caster and Spell.cpp:1794 resolved m_caster->GetGuardianPet() -- a pet has
-- no pet.  Nothing on 200754 is cast by the pet.
--
-- EffectMiscValue1 = 2 is POWER_FOCUS.  A 0 there would energize mana, which a
-- pet does not use, and the effect would be silently wasted.
